const { uppercase } = require('./formatters/uppercase');
const { reverse } = require('./formatters/reverse');

const formatters = {
  uppercase: uppercase,
  reverse: reverse,
};

function getFormatter(name) {
  return formatters[name] || null;
}

function process(text, formatterName) {
  const fn = getFormatter(formatterName);
  if (!fn) return { error: `Unknown formatter: ${formatterName}` };
  return { result: fn(text) };
}

function listFormatters() {
  return Object.keys(formatters);
}

module.exports = { process, getFormatter, listFormatters, formatters };

