const assert = require('assert');
const { process, getFormatter, listFormatters, formatters } = require('../pipeline');
let passed = 0, failed = 0;
function runTest(name, fn) {
  try { fn(); passed++; console.log('PASS: ' + name); }
  catch(e) { failed++; console.log('FAIL: ' + name + ' — ' + e.message); }
}

// Existing formatters still work
runTest('uppercase works', () => {
  const r = process('hello', 'uppercase');
  assert.strictEqual(r.result, 'HELLO');
});
runTest('reverse works', () => {
  const r = process('hello', 'reverse');
  assert.strictEqual(r.result, 'olleh');
});
runTest('unknown formatter', () => {
  const r = process('hello', 'nope');
  assert.ok(r.error);
});

// New markdown formatter
runTest('markdown registered', () => {
  assert.ok(formatters.markdown, 'markdown formatter must be registered');
});
runTest('markdown wraps in bold', () => {
  const r = process('hello', 'markdown');
  assert.strictEqual(r.result, '**hello**');
});
runTest('markdown converts newlines', () => {
  const r = process('line1\nline2', 'markdown');
  assert.strictEqual(r.result, '**line1<br>line2**');
});
runTest('markdown empty string', () => {
  const r = process('', 'markdown');
  assert.strictEqual(r.result, '****');
});
runTest('markdown non-string', () => {
  const r = process(123, 'markdown');
  assert.strictEqual(r.result, '');
});

// Chaining: process with array of formatter names
runTest('chain two formatters', () => {
  const r = process('hello', ['uppercase', 'reverse']);
  assert.strictEqual(r.result, 'OLLEH');
});
runTest('chain with markdown', () => {
  const r = process('hello', ['markdown', 'uppercase']);
  assert.strictEqual(r.result, '**HELLO**');
});
runTest('chain single formatter', () => {
  const r = process('hello', ['reverse']);
  assert.strictEqual(r.result, 'olleh');
});
runTest('chain with unknown fails', () => {
  const r = process('hello', ['uppercase', 'nope']);
  assert.ok(r.error);
});

runTest('list includes markdown', () => {
  const list = listFormatters();
  assert.ok(list.includes('markdown'), 'markdown must be in list');
  assert.ok(list.includes('uppercase'));
  assert.ok(list.includes('reverse'));
});

console.log('\n' + passed + '/' + (passed+failed) + ' tests passed');
if (failed > 0) process.exit(1);
